from pwn import *
import gmpy2
from Crypto.Util.number import *

def analyze_values(target, v1, v2, result):
    mod = 2**256

    print(f"\nAnalyzing relationships:")
    print(f"target = {hex(target)}")
    print(f"v1 = {hex(v1)}")
    print(f"v2 = {hex(v2)}")
    print(f"result = {hex(result)}")

    # Check if result = v1 * v2 mod 2^256
    if (v1 * v2) % mod == result:
        print("Found relationship: result = v1 * v2 mod 2^256")

    # Try to find x where target = (x * v1) mod 2^256 or target = (x * v2) mod 2^256
    try:
        inv_v1 = gmpy2.invert(v1, mod)
        x1 = (target * inv_v1) % mod
        if (x1 * v1) % mod == target:
            print(f"Found x1: {hex(x1)} where target = (x1 * v1) mod 2^256")
            return x1
    except:
        print("No inverse for v1")

    try:
        inv_v2 = gmpy2.invert(v2, mod)
        x2 = (target * inv_v2) % mod
        if (x2 * v2) % mod == target:
            print(f"Found x2: {hex(x2)} where target = (x2 * v2) mod 2^256")
            return x2
    except:
        print("No inverse for v2")

    # Check if target = (v1 * v2 * k) mod 2^256
    try:
        if v1 * v2 != 0:
            k = (target * gmpy2.invert(v1 * v2, mod)) % mod
            if (v1 * v2 * k) % mod == target:
                print(f"Found k: {hex(k)} where target = (v1 * v2 * k) mod 2^256")
                return k
    except:
        print("No k relationship found")

    # Check for square roots
    try:
        if v1 != 0:
            sqrt_v1 = gmpy2.isqrt(v1)
            if sqrt_v1 * sqrt_v1 == v1:
                print(f"v1 is a perfect square: sqrt(v1) = {hex(sqrt_v1)}")
    except:
        pass

    try:
        if v2 != 0:
            sqrt_v2 = gmpy2.isqrt(v2)
            if sqrt_v2 * sqrt_v2 == v2:
                print(f"v2 is a perfect square: sqrt(v2) = {hex(sqrt_v2)}")
    except:
        pass

    return None

def main():
    # Connect to server
    conn = remote('crypto.chal.csaw.io', 5000)

    while True:
        try:
            # Get target
            line = conn.recvline().decode().strip()
            target = int(line, 16)
            print(f"Target: {hex(target)}")

            # Get v1, v2
            line = conn.recvline().decode().strip()
            v1, v2 = map(lambda x: int(x, 16), line.strip('()').split(','))
            print(f"v1: {hex(v1)}, v2: {hex(v2)}")

            # Get result
            line = conn.recvline().decode().strip()
            result = int(line, 16)
            print(f"Result: {hex(result)}")

            # Analyze values
            guess = analyze_values(target, v1, v2, result)

            if guess is None:
                print("No direct relationship found")
                # Try target / v1 as guess
                try:
                    guess = (target * gmpy2.invert(v1, 2**256)) % (2**256)
                except:
                    guess = target  # Default to target if no relationship found

            # Send guess
            print(f"Sending guess: {hex(guess)}")
            conn.sendline(hex(guess)[2:])  # Remove '0x' prefix

            # Get response
            resp = conn.recvline().decode().strip()
            print(f"Response: {resp}")

            if 'flag{' in resp:
                print("Found flag!")
                print(resp)
                break

        except EOFError:
            print("Connection closed")
            break
        except Exception as e:
            print(f"Error: {e}")
            break

    conn.close()

if __name__ == '__main__':
    main()
